// FUNCTION: BFME2 0x00306183 size=149 name=?xferRandomVariable@@YAAAVXfer@@AAV1@AAVGameClientRandomVariable@@@Z evidence=N:ledger tier=B hypothesis:K

Xfer &xferRandomVariable(Xfer &xfer, GameClientRandomVariable &variable)
{
	xfer.Version1();
	Real low = 0.0f;
	Real high = 0.0f;
	int type = 0;
	if (xfer.IsStoring())
	{
		low = variable.m_low;
		high = variable.m_high;
		type = variable.m_type;
	}
	xfer == low;
	xfer == high;
	XferDistributionType(&xfer, &type);
	if (!xfer.IsStoring())
		variable.setRange(low, high, (GameClientRandomVariable::DistributionType)type);
	return xfer;
}

