// FUNCTION: BFME2 0x00306232 size=204 name=?Rva00306232XferScience@@YAPAVXfer@@PAV1@PAW4ScienceType@@@Z evidence=?:placeholder tier=B hypothesis:K
Xfer *XferScience(Xfer *xfer, ScienceType *science)
{
	if (xfer->IsLightCRC())
		xfer->XferEnum("ScienceType", science, 4);
	else if (xfer->IsStoring())
	{
		AsciiString name = TheScienceStore->getInternalNameForScience(*science);
		*xfer == name;
	}
	else
	{
		AsciiString name;
		*xfer == name;
		*science = TheScienceStore->getScienceFromInternalName(name);
		if (*science == SCIENCE_INVALID)
			throw XferException(0, 0);
	}
	return xfer;
}

